/// Go evaluates exactly `Chunk.NumRows()` rows; a malformed Rust expression must not silently
/// truncate the result through iterator `zip` semantics.
#[test]
fn generated_time_vectors_reject_short_argument_columns() {
    let lhs = Rc::new(LiteralExpression::new(
        Column::Times(vec![None]),
        FieldType::default(),
    ));
    let rhs = Rc::new(LiteralExpression::new(
        Column::Durations(vec![None, None]),
        FieldType::new(0),
    ));
    let signature =
        builtinAddDatetimeAndDurationSig::new(BuiltinBase::new(lhs, rhs, FieldType::new(0)));
    let error = signature
        .vecEvalTime(
            &EvalContext::default(),
            &Chunk::new(2),
            &mut Column::default(),
        )
        .expect_err("short columns must be rejected instead of truncating the output");

    assert_eq!(error.to_string(), "time column has 1 rows, expected 2");
}

